"use client";
import { EosConnectLink } from "@/components/application/eos/connect-link";
import { EosGradientBanner } from "@/components/application/eos/gradient-banner";

/** Morrow ··· Coffer in frosted tiles on a gradient, and in white tiles on the page. */
export default function EosConnectLinkDemo() {
  return (
    <div style={{ display: "grid", gap: 18, justifyItems: "center", width: "100%", maxWidth: 560, margin: "0 auto" }}>
      <EosGradientBanner gradient="dawn" shape="card" height={220} style={{ width: "100%" }}>
        <EosConnectLink from={{ label: "Morrow" }} to={{ label: "Coffer", app: "books" }} tone="frosted" size="lg" />
      </EosGradientBanner>
      <EosConnectLink from={{ label: "Mail", app: "mail" }} to={{ label: "Sheet", app: "sheet" }} tone="white" size="md" />
    </div>
  );
}

